#!/usr/bin/env bash
# RVC-R15: deterministic file-backed Runtime positive-convergence verifier.
# Uses a real file-backed Run repository plus the concrete File owner, alongside
# focused contract/crash fixtures; no public LLM.

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

source "$ROOT_DIR/scripts/lib/go-test-must-run.sh"

ARTIFACT_DIR="$(realpath -m "${WORKORCH_E2E_ARTIFACT_DIR:-${TMPDIR:-/tmp}/workorch-e2e/runtime-positive-convergence/$(date -u +%Y%m%dT%H%M%SZ)}")"
REPOSITORY_E2E_ARTIFACT_DIR="$(realpath -m "$ROOT_DIR/.workorch-e2e")"
if [[ "$ARTIFACT_DIR" == "$REPOSITORY_E2E_ARTIFACT_DIR" || "$ARTIFACT_DIR" == "$REPOSITORY_E2E_ARTIFACT_DIR/"* ]]; then
  echo "WORKORCH_E2E_ARTIFACT_DIR must not point to the repository .workorch-e2e directory" >&2
  exit 2
fi
mkdir -p "$ARTIFACT_DIR"
LOG="$ARTIFACT_DIR/verify.log"

echo "runtime positive-convergence file verifier" | tee "$LOG"
echo "artifacts=$ARTIFACT_DIR" | tee -a "$LOG"

run_pkg() {
  local pkg="$1"
  shift
  echo "==> go test $pkg $*" | tee -a "$LOG"
  if ! run_go_test "$pkg" "$@" -count=1 2>&1 | tee -a "$LOG"; then
    echo "FAIL: $pkg $*" | tee -a "$LOG"
    echo "artifacts retained at $ARTIFACT_DIR" >&2
    exit 1
  fi
}

# RVC-R5/R6/R7/R8 contract gates: effect scope, seal, repair directive, MCP normalize.
run_pkg ./internal/pkg/workorchruntimecontract \
  -run 'TestRuntimeEffectScope|TestValidateEffectScopes|TestRequiredOutputRequiresExplicitEffectScopes|TestRuntimeOperationDescriptorEffectScope|TestRuntimeOperationExecutionRecord|TestRuntimeRepairDirective|TestRuntimeSemanticCorrectionDirectiveIsManifestBoundAndDetached|TestRuntimeCandidateContextPreservesValidationQualityObservation|TestRuntimeRepairSurfaceObservationIsFactOnlyAndBounded|TestRuntimeRepairSurfaceConfirmationRecordProvidesTypedReplayFence|TestRuntimeRepairSurfaceConfirmationSequenceEndsAtTerminalDisposition|TestRuntimeTermination|TestFailureClassDisposition|TestResolveExpectedEffectScope|TestResolveOperationIdempotencyClass|TestSealRejects|TestSealAccepts|TestSealMCPCapability|TestRuntimeOperationDescriptorsAreStableCompleteAndUnique|TestFeasibleOperationKindsIntersectAcceptedCapabilitiesAndEffect|TestValidateAssessmentDispositionPreservesOriginalObservation|TestValidateRuntimeOperationContract|TestMCPRegistryKindNormalizationDoesNotBackfillOperationKind|TestRuntimeOperationGovernanceGrant|TestRuntimeCandidateRequiresAcceptedOperationWhenDeclared|TestRuntimeProfileDeclaredSelectorCandidatesAreBoundedAndAffectEquality|TestRuntimeBootstrapRecipeIsBoundedOrderedAndAffectsProfileEquality|TestRuntimeCandidatePrefixChangesWithProfileDeclaredSelectorBinding'

# One generic recipe cannot close unrelated detailed CWIs. Definition-owned
# requirements, Shell-owned applicability and the SM-2 aggregate reverse proof
# remain exact across normalization, receipt and opaque reload.
run_pkg ./internal/pkg/workorchruntimecontract \
  -run '^(TestCompileRuntimeValidationProofRequirementsKeepsDistinctExactCWIs|TestRecipeNeutralCWIRequirementBindsEveryCompatibleReadyOwnerRecipe|TestRuntimeValidationProofAuthorityRejectsDuplicateNormalizationLaundering|TestRuntimeValidationSurfaceRejectsNativeCheckReuseAcrossReadyAndPreparationRecords|TestShellAdmissibilityAcquisitionRejectsDuplicateProofAuthorityBeforeNormalization|TestCoverageEvidenceProofValidateRejectsCrossKindProofShapes)$'
run_pkg ./internal/modules/blocks/shell/biz \
  -run '^(TestDefaultManagedValidationRecipeDoesNotManufactureCWISpecificProof|TestDefaultManagedValidationRecipeCreditsExactOwnerNativeAttestation|TestShellValidationSurfaceKeepsPerCWIMixedReadiness|TestRawWorkspaceMarkerCannotCreditManagedValidation|TestRuntimeAdapterIgnoresRawManagedValidationMarkers|TestGoTestJSONOutputEventCannotForgeNativePass|TestShellOwnerReconciliationDoesNotTreatGenericRecipeSuccessAsCWIProof|TestShellOwnerAdmissibilityDoesNotPublishUnsupportedNativeProofRecipe)$'
run_pkg ./internal/modules/kernel/orchestrator/biz/runtime \
  -run '^(TestRuntimeAggregateShellValidationProofApplicabilitySurvivesSerializationAndFailsClosed|TestBuiltinSoftwareDevAllManagedCWIsCloseThroughTypedNativeProofPipeline)$'

run_pkg ./internal/modules/application/workorchd/biz/appservice/activationcore \
  -run '^(TestRuntimeBootstrapMCPOnlyValidationDoesNotEnlistShellManagedProof|TestRuntimeBootstrapRejectsManagedValidationWithoutProfileOwnedAcquisition)$'
run_pkg ./internal/modules/kernel/orchestrator/biz \
  -run '^(TestRuntimeValidationExecutionBindingComesOnlyFromSealedCWIAndOwnerCatalog|TestRuntimeShellExecutorSealsExactPersistedValidationAttestation|TestRuntimeStateRepositoryRejectsAmbiguousRawActivationEvidencePoliciesWithoutRewriting)$'

# File-backed owner aggregates use one crash-safe canonical publication
# boundary; concurrent readers see a complete old or new generation and a
# post-rename durability error cannot leave an old process cache authoritative.
run_pkg ./internal/pkg/repository/filecommit \
  -run '^(TestPublishReplacesCanonicalWithDurableCompleteFile|TestPublishSynchronizesNewDirectoryChainBeforeCanonicalRename|TestPublishPreRenameFailurePreservesCanonicalAndRemovesTemp|TestPublishReportsPublishedButDurabilityUnacknowledged|TestPublishConcurrentReadersObserveOnlyCompleteGenerations)$'
run_pkg ./internal/pkg/repository/file \
  -run '^(TestSaveMapPublishesOnlyCompleteOldOrNewLargeJSON|TestSaveMapPrePublicationFailurePreservesCanonicalAndCache|TestSaveMapPostPublicationSyncFailureInvalidatesOldCache|TestSaveMapHoldsCacheFenceThroughParentDirectorySync|TestLoadMapTreatsOnlyCanonicalPathAsAuthority)$'

# Workspace persists its owner-private RunProjectionCursor without publishing
# an indistinguishable public WorkspaceStateChanged event.
run_pkg ./internal/modules/kernel/workspace/biz \
  -run '^(TestWorkspaceRunProjectionPersistsCursorWithoutRepublishingUnchangedPublicState|TestWorkspaceRunProjectionFreshOwnerAdvancesCursorWithoutPublicStateNotification)$'

# RVC-R9/R10 seal executions + evidence adjudication + claim/fence path via controller fixtures.
run_pkg ./internal/modules/kernel/orchestrator/biz/runtime \
  -run 'TestAdjudicateEvidenceKind|TestSealDispatchCreatesOperationExecution|TestPositiveConvergenceFixture_|TestEvaluateCandidateAdmission|TestActiveRejectedOperationShapes|TestAdmitCandidateProposalAtomicallyExhaustsSingleShapeFrontier|TestAdmitCandidateProposalIdentifiesInvalidDuplicateByCandidateStructure|TestAdmitAndSealCandidateAttemptKeepsRejectedAndAcceptedDuplicateDeliveriesIdempotent|TestRuntimeAggregateRejectsTerminalDecisionWithPendingCandidateAttempt|TestRuntimeAggregateRequiresReducerTransitionAfterCandidateAttemptOneFailure|TestReduceRuntimeStateDeterminedTerminalFailureOverridesPendingPrerequisite|TestRuntimeControllerCandidateRetryExhaustionClosesAtomically|TestRuntimeControllerTerminalDriveFailureClosesPendingCandidate|TestReduceRuntimeStateRepairableAssessmentDoesNotTerminal|TestReduceRuntimeStateSameFocusRepairThenReassess|TestReduceRuntimeStateRepairBudgetExhausted|TestReduceRuntimeStateValidationOnlyCapTerminalsWithoutStateChange|TestAssessmentForCurrentFocusRetainsAuditAndUsesRevisionFreshness|TestRuntimeControllerOwnsDispatch|TestRuntimeControllerCommitsTypedAssessment|TestRuntimeControllerCommitsGovernanceContinue|TestRejectedGovernanceResumeReceiptBindsResumeDispatchAcrossFreshLoad|TestRejectedGovernanceResumeReceiptRejectsOriginOrUnknownFeedbackDispatch|TestRecordOperationGovernanceRequiredDoesNotUseExecutionRepair|TestRuntimeControllerRecoversOwnerCommittedReceiptWithoutReplayingSideEffect|TestRuntimeControllerRecoversReceiptWhenOwnerResponseIsLostAfterCommit|TestRuntimeControllerTurnsClaimedWithoutReceiptIntoOutcomeUnknownWithoutReplay|TestRuntimeControllerDoesNotReplayClaimedManagedValidationWithoutReplayProof|TestRuntimeControllerOperationReceiptFenceAndTerminalUniqueness|TestRepairSurfaceConfirmationCreatesFreshStateChangeAuthority|TestRejectedRepairSurfaceFailsBeforeAnotherValidationCandidate|TestRuntimeControllerRejectsSplitCASRecoveryBudget|TestReduceRuntimeStateRoutesExhaustedProviderTransportToTerminal|TestCapabilityStatePrerequisiteRequiresOwnerConfirmedSnapshot|TestPrerequisiteStaleInvalidatesProposalAndReacquiresWithoutCandidateDebt|TestRepairLedgerTransitionsAreOrchestratorOwned|TestAdvanceSatisfiedCoverageFocusDropsPriorFocusTargetFacts'

# VPC: receipt quality and effective-progress/no-progress replay remain part
# of the deterministic file gate, not only of an in-process unit suite.  The
# real Shell owner matrix also proves a present invalid/over-bound marker cannot
# degrade the atomic marker+parser candidate transaction to parser-only scope.
run_pkg ./internal/modules/blocks/shell/biz \
	-run 'Test.*Validation|Test.*GoTest.*Observation|TestShellOwnerDoesNotInferFailureTargetFromValidationCommand|TestShellOwnerFailureTargetMarkerAndParserCandidateUnionFailsClosed|TestShellFailureTargetMarkerOutsideSealedScopeIsRejected|TestShellFailureCandidateMergeRejectsCombinedBoundOverflow'

# VPC-8 owner-observation boundary: MCP may bind an explicit structured
# failure target only through the exact completed dispatch + rejected receipt
# + receipt-derived evidence + current catalog chain. The selected integration
# also rejects generic ingress, owner_committed, missing/duplicate/drifted
# evidence, receipt drift and mutable catalog drift after serialization.
run_pkg ./internal/modules/kernel/orchestrator/biz/runtime \
  -run 'TestMCPOwnerObservedFailureTargetBindsThroughEventHubAndFileSnapshot'

# SM-3 sealed target authority is immutable and bijective. Fresh load must
# reject missing/duplicate/hash/manifest/operation drift instead of rebuilding
# authorization from current owner facts.
run_pkg ./internal/pkg/workorchruntimecontract \
  -run '^(TestRuntimeDispatchTargetAuthorizationFreshLoadRejectsTamper|TestRuntimeDispatchAdmissionLineageBindsCandidateManifestHash|TestRuntimeDispatchTargetAuthorizationRequiresOperationBijectionOnlyForOperationCandidates|TestRuntimeDispatchOperationTargetAuthorizationForOperationRequiresExactSealedOperation|TestRuntimeDispatchRecordValidateIntrinsicRejectsCoordinatedAuthoritySubstitution|TestRuntimeCandidateAttemptAcceptedRequiresIndependentTargetAuthorizationCommitment)$'

# Request-session manifest authority, the global evidence chronology, and the
# assessment pre-seal/post-seal split are all fresh-load contracts. These exact
# tests reject normalization laundering and coordinated self-hash rewrites.
run_pkg ./internal/pkg/workorchruntimecontract \
  -run '^(TestRuntimeCandidateContractManifestRawCanonicalRejectsNormalizationLaundering|TestRuntimeDispatchCoverageBindingSnapshotFreshLoadRejectsTamper|TestRuntimeDispatchAdmissionLineageBindsIndependentManagedValidationRecipe|TestRuntimeGovernanceResumeAdmissionInheritsManagedValidationRecipePerHop|TestRuntimeCandidateAttemptAcceptedManagedValidationRequiresIndependentRecipeCommitment|TestStableRuntimeEvidenceFactHashBindsExactRejectedProjection|TestRuntimeOperationExecutionEvidenceCommitRequiresIndependentFactIdentity|TestValidateRuntimeEvidenceLedgerSequenceAcceptsTypedGlobalChainAndResumeClone|TestValidateRuntimeEvidenceLedgerSequenceRejectsGlobalRevisionTamper|TestValidateRuntimeEvidenceLedgerSequenceRejectsOrphanDuplicateAndAssessmentKind|TestValidateRuntimeEvidenceLedgerSequenceRejectsGovernanceCreditPollution|TestValidateRuntimeEvidenceLedgerSequenceRejectsAssessmentTamper|TestRuntimeDefinitionFocusAssessmentSourceIsExactSeedProjection|TestRuntimeAssessmentAuthoritySourceIsSeedRootedForActiveDispatch|TestRuntimeAssessmentAuthorityAndAdjudicationRejectRawNormalizationLaundering|TestRuntimeAssessmentSourceProjectionRejectsCoordinatedFocusAndFactRewrite)$'

# The accepted attempt owns a complete pre-dispatch target projection, while a
# partial confirmed-File all-of transaction owns no stale mutable target or
# state-change directive. Both fresh-load gates reject coordinated rewrites.
run_pkg ./internal/modules/kernel/orchestrator/biz/runtime \
  -run '^(TestRuntimeAggregateFreshLoadRejectsCoordinatedDispatchProjectionAndSealRewrite|TestConfirmedRepairMultiOperationReceiptChainSurvivesRestartAndDuplicate|TestConfirmedRepairCommitmentFreshLoadRejectsDeletionAndCoordinatedTamper|TestAcceptedConfirmedRepairManifestLineageRejectsMissingDuplicateAndBodyDrift|TestConfirmedRepairMultiOperationRejectsSecondReceiptFromOriginalRevision|TestPendingConfirmedRepairTransactionRejectsBrokenReceiptEvidenceAndRevisionChain|TestPendingConfirmedRepairTransactionRejectsMutableAuthorityAndFreshnessDrift|TestRefreshExhaustedConfirmedRepairKeepsMutableAuthorityRetired)$'

# Semantic binding authority must replay from persisted provider documents and
# owner feasibility facts across multi-batch/history recovery. Assessment
# disposition/proofs must replay from the pre-seal input and use double entry.
run_pkg ./internal/modules/kernel/orchestrator/biz/runtime \
  -run '^(TestRuntimeSemanticBindingPreimageRejectsCoordinatedProjectionRewrite|TestRuntimeSemanticBindingPreimageRequiresArchivedHistoryOwnerFacts|TestRuntimeSemanticMultiBatchFeasibilityMergeRecoversAfterResponseLoss|TestRuntimeSemanticCatalogInvalidationDoesNotReplanSettledCWI|TestRuntimeSemanticSettlementRetiresGenerationWhenDependencyBecomesEligible|TestRuntimeAssessmentAdjudicationRejectsCoordinatedDispositionAndProofRewrite|TestRuntimeAssessmentAdjudicationSurvivesRestartAndRawCloneDetaches)$'

# Managed-validation causation keeps entry A, sealed scope {A,B}, and
# diagnostic candidate B distinct; missing/extra/outside shapes fail closed.
run_pkg ./internal/modules/kernel/orchestrator/biz/internal/proof \
  -run '^(TestValidationFailureObservationMatchesSealedOperationUsesSealedValidationScope|TestValidationFailureObservationMatchesSealedOperationRejectsUnsealedOrInvalidFacts)$'

# The repair-owner request/response DTO binds the protocol descriptor, expected
# resource revision, immediate owner-CAS revision and terminal response
# sequence independently of the concrete File adapter.
run_pkg ./internal/pkg/workorchruntimecontract \
  -run '^(TestRuntimeRepairSurfaceObservationIsFactOnlyAndBounded|TestRuntimeRepairSurfaceConfirmationSubjectIsProtocolBound|TestRuntimeRepairSurfaceConfirmationRecordProvidesTypedReplayFence|TestRuntimeRepairSurfaceConfirmationSequenceEndsAtTerminalDisposition)$'

# Generic SM-4 persistence recovery is one request-bound transaction: typed
# Run-owner outcome, technical guard disposition and successor lease are sealed
# together. Plain conflict/Temporary input has no retry authority.
run_pkg ./internal/pkg/workorchruntimecontract \
  -run '^(TestRuntimeNonTerminalRecoveryRequestIDExcludesRedeliveryTimeButBindsAdmissionFence|TestRuntimeNonTerminalRecoveryRecordBindsSharedCASBudgetAndSuccessor|TestRuntimeDriveLeaseRecoveryRequestLegalityIsNarrow)$'
run_pkg ./internal/modules/kernel/orchestrator/biz/runtime \
  -run '^(TestRuntimeNonTerminalRecoveryTypedOutcomeGateRejectsGenericErrors|TestRuntimeNonTerminalRecoveryAtomicallyPersistsBudgetRecordAndUniqueLease|TestRuntimeNonTerminalRecoveryResponseLossReloadsPersistedRecordAndLease|TestRuntimeNonTerminalRecoveryExhaustionKeepsDurableCappedSuccessor|TestRuntimeAdministrativeTerminationRetiresRunningNonterminalRecoveryAuthority|TestRuntimeTerminalScheduledLeaseStaleClaimRematerializesExactAuthorizedGenerationAfterRestart|TestRuntimeTerminalDeliveryHistoricalRetiredGenerationDoesNotBlockLaterRematerialization)$'

# Real Shell/EventHub execution can emit only a finite-scope observation. It
# cannot publish direct target authority, supplement selector-only scope from a
# mutable manifest, or bypass the exact receipt/File-confirmation transaction.
# The real File owner is also queried before and after a workspace mutation so
# only the revision-bound stale -> refresh -> new-fence sequence can proceed.
run_pkg ./internal/modules/kernel/orchestrator/biz/runtime \
  -run '^(TestShellOwnerObservedFailureTargetBindsThroughEventHubAndFileSnapshot|TestShellOwnerSelectorOnlyValidationNeverCreatesRepairObservation|TestRuntimeAggregateRejectsDirectShellFailureTargetAuthority|TestRejectedManagedValidationCrossOwnerTargetObservationFailsClosed|TestRejectedManagedValidationDirectShellTargetObservationFailsClosed|TestManagedValidationReceiptRejectsDirectDiagnosticTargetsAtCommitAndFreshLoad|TestManagedValidationReceiptRejectsForeignOrMismatchedValidationFailureObservation|TestOperationReceiptFeedbackScopeRejectsDriftAtCommitAndFreshLoad|TestRuntimeAggregateRejectsValidationFailureObservationWithoutExactShellReceipt|TestRuntimeAggregateRequiresCanonicalValidationFailureReceiptCopies|TestValidationFailureObservationRequiresEvidenceCommittedReceiptTransaction|TestRepairSurfaceConfirmationRequiresSealedOwnerAtCommitAndFreshLoad|TestRepairSurfaceConfirmationTerminalResponseFencesLaterRevisions|TestRepairSurfaceConfirmationStaleRevisionRequiresPrerequisiteReplanBeforeFreshResponse|TestRepairSurfaceConfirmationFencesInFlightResponseAfterAdministrativeTermination|TestRepairSurfaceConfirmationExactReplayRemainsNoOpAfterAdministrativeTermination|TestRuntimeAggregateRejectsCoordinatedRepairSurfaceRequestFenceTamper|TestRuntimeRepairSurfaceConfirmationChronologyIsGlobalAcrossObservations|TestCurrentRuntimeRepairSurfaceConfirmationPlanEligibilityMatrix|TestRuntimeRepairSurfaceConfirmationRequestIDBindsRevisionAndRefreshLineage|TestValidationFailureRepairAuthorityRequiresExactOwnerConfirmationAtCommitAndFreshLoad|TestRuntimeDriveLeaseAdministrativeTerminationReissuesRetiredGenerationOnlyWhileDeliveryPending|TestRuntimeControllerExecutesManagedValidationWithSealedRecipeAfterResourceRefresh|TestRejectedTypedValidationWithoutFailureTargetOpensProfileRepairGeneration)$'

# Run-owner/SM-2 persistence must reject bypass before File/provider work and
# preserve only sealed causation across receipt CAS, reload, and owner isolation.
run_pkg ./internal/modules/kernel/orchestrator/biz \
  -run '^(TestConfirmFileRuntimeRepairSurfaceRequiresExactRequestFence|TestRuntimeDecisionConfirmsValidationRepairSurfaceBeforeProvider|TestRuntimeSynchronousIngressRejectsPersistedDriveLeaseBeforeOwnerCalls|TestRuntimeSynchronousIngressSingleGateBlocksDuplicateRepairSurfaceQuery|TestRuntimeSynchronousIngressCanceledExitMountsLatchedLifecycleLease|TestRuntimeSynchronousIngressRejectsDrainingWorkspaceBeforeOwnerWork|TestScheduledRuntimeDriveFailureRebasesToPersistedTerminalAuthority|TestScheduledRuntimeDriveTerminalRebasePreventsFallbackLease|TestScheduledRuntimeDriveTerminalRebaseAdoptsExistingPersistedLease|TestScheduledRuntimeDriveTerminationRetiresClaimedLeaseBeforeDeliveryRetry|TestWorkspaceRuntimeQuiescenceAdministrativeTerminationAdmitsRetiredClaimedDeliverySuccessor|TestWorkspaceRuntimeQuiescenceFinalAckBeforeRetiredGenerationScheduleReleasesGate|TestTerminalDeliveryLeaseScheduleCASRebasesFinalAcknowledgementAndReleasesGate|TestTerminalDeliveryRecoveryBudgetCASRebasesPartialAcknowledgementOnce|TestTerminalDeliveryRecoveryBudgetCASRebasesFinalAcknowledgementWithoutSpend|TestTerminalDeliveryRecoveryBudgetPostCommitResponseLossPersistsSuccessor|TestTerminalDeliveryLeaseSchedulePostCommitResponseLossMountsExactSuccessor|TestTerminalDeliveryExactRunningLeaseCleanupPostCommitResponseLossReleasesGate|TestScheduleRuntimeDriveRetainsGateAndDefersRejectedSubmissionToSettlementPump|TestRuntimeDriveGateSettlementPumpRearmsAfterFrameworkTickRejection|TestRuntimeDriveGateSettlementPumpSurvivesOneShotSubmissionRejection|TestRuntimeDriveGateFreshNoLeaseReleaseActivatesConcurrentDormantHandoff|TestRuntimeDriveGateSettlementMergeCannotRedormantActiveSettlement|TestRetainOrAcquireRuntimeDriveGateSettlementTakesGateAfterStaleSnapshotRelease|TestRuntimeTerminationHandoffWaitsForExactGateOwnerExit|TestRuntimeTerminationCASResponseLossEntersCanonicalDeliverySettlement|TestRuntimeStartupRecoveryAdministrativeRetiredMarkerMaterializesExactSuccessor|TestRuntimeStartupRecoveryRematerializesStaleAdministrativeTerminalSuccessor|TestRuntimeNonTerminalRecoveryOuterCASGenerationZeroCommitsOneAtomicSuccessor|TestRuntimeNonTerminalRecoveryOuterOwnerTransientUsesSharedCASBudgetOnly|TestRuntimeNonTerminalRecoveryOuterPostCommitResponseLossReloadsWithoutSecondCAS|TestRuntimeNonTerminalRecoveryOuterExhaustionKeepsCappedDurableSuccessor|TestRuntimeNonTerminalRecoveryOuterRejectsUntypedRetryAuthority|TestRuntimeNonTerminalRecoveryAtomicLinearizationRejectsTornPersistence|TestRuntimeBusinessFailureFactTypedCASUsesAtomicNonTerminalRecovery|TestRuntimeStateRepositoryValidationFailureObservationReceiptCrashRestartIsAtomic|TestRuntimeStateRecordPreservesRepairSurfaceConfirmationFenceAcrossOpaqueReload|TestRuntimeFileBackedRestartRejectsCrossOwnerTargetObservationAtomically)$'

run_pkg ./internal/modules/kernel/orchestrator/biz/runtime \
  -run 'TestAcceptedValidationEvidencePreservesRepairLedgerAndUsesAssessmentRevisionFreshness|TestAcceptedDurableStateChangeReopensValidationWindowWithoutResettingMandatoryAssessmentRepairDebt|TestAcceptedDurableStateChangeRequiringAssessmentDoesNotResetRepairProgressWindow|TestReduceRuntimeStateWithDirectiveAllowsBoundedOwnerWorkspaceScopeWithoutConcreteSnapshots|TestEvaluateCandidateAdmissionAllowsFiniteOwnerGroundedWorkspaceScopeThroughFileAdmissibility'

# RVC-R14 Run-owner typed startup inventory.
run_pkg ./internal/modules/blocks/run/... \
  -run 'TestBuildRuntimeRecoveryInventoryContainsOnlyRunOwnedOpaqueFacts|TestGMMR1SM4RecoveryInventoryAvailableAfterSetupBeforeRun|TestRecoveryInventoryDoesNotInspectOrchestratorState'

# Concrete File owner consumes only an already validated typed governance grant.
run_pkg ./internal/modules/blocks/file/... \
  -run 'TestRuntimeAdapterPatchApplyConsumesValidatedApprovalGrant|TestRuntimeAdapterPatchApplyAllowsLargeWorkspaceLocalSourceChange|TestSupportedRuntimeOperationVariantsMatchDescriptor|TestRuntimeAdapterAcquireRuntimeTargetSelectionIsCardinalityBounded|TestRuntimeAdapterUniqueWorkspaceEntryProspectiveAdmissionMatrix|TestRuntimeAdapterAcquireProfileDeclaredTargetSelectionOnlyIntersectsCandidates|TestFileOwnerReconciliationObservesRealizedProspectiveTargetWithoutReopeningCreateAdmission|TestFileOwnerReconciliationSelectorCardinalityAndProspectiveMatrix|TestFileOwnerConfirmsOnlyCurrentRegularRepairSurface'

# Only an owner-persisted governance receipt may suspend an operation for approval.
run_pkg ./internal/modules/kernel/orchestrator/biz \
  -run 'TestRuntimeOperationExecutionResultUsesOnlyPersistedReceiptGovernance'

run_pkg ./internal/modules/blocks/git/... \
  -run 'TestCapabilityStateReceiptStoreIsDurableAndIdempotent|TestSupportedRuntimeOperationVariantsMatchDescriptor|TestValidateCapabilityStatePredecessorReceiptsRequiresExactDurableBinding|TestGitOwnerCapabilityBoundAdmissibilityRejectsMismatchedProbeBindingAsStale'

# Candidate attempt 0/1, file-backed restart idempotency, feasibility, and
# sealed-operation owner isolation. The cross-owner receipt case proves that an
# operation cannot smuggle another component's target authority through the
# Run-owner persistence boundary, including across a fresh-process restart.
run_pkg ./internal/modules/kernel/orchestrator/biz \
	-run 'TestDriveRuntimeFileBackedRunExecutesDurableFileOwnerAndRestarts|TestRuntimeFileBackedGroundedTargetStateSequenceRestartsAtCommittedBoundaries|TestRuntimeFileBackedEmptyWorkspaceCreationSelectionContinuesThroughCandidate|TestRuntimeFileBackedEmptyWorkspaceCreationReceiptCrashRestartDoesNotReplayCreate|TestRuntimeFileBackedBoundedWorkspaceScopeAllowsNewDeliverable|TestRuntimeFileBackedAmbiguousTargetSelectionFailsWithoutProvider|TestRuntimeFileBackedAbsentTargetSelectionFailsWithoutProvider|TestRuntimeFileBackedWorkspaceDeliverableWithoutProfileArtifactFailsWithoutProvider|TestRuntimeFileBackedMCPOwnerFailureTargetReceiptRestartMatrix|TestRuntimeFileBackedPatchReplayProofRestartsAfterOwnerReceiptCASFailure|TestRuntimeStartupRecoveryDeliversPendingTerminalThroughOwnerChain|TestDriveRuntimeFileBackedRestartRecoversCrashAfterOwnerReceipt|TestRuntimeFileBackedClaimEvidenceAndDispatchCloseCrashMatrix|TestRuntimeFileBackedGitCapabilityStateSequenceMatrix|TestRuntimeFileBackedGitRestartAfterInitEvidenceCommitContinuesSequence|TestRuntimeFileBackedGitQueryReceiptCrashBeforePrerequisiteCommitReusesSnapshot|TestRuntimeFileBackedGitSnapshotCommitResponseLossRestartReusesCommittedSnapshot|TestRuntimeFileBackedGitStaleRefreshCrashRestartDoesNotReplayOldDispatch|TestRuntimeFileBackedPatchVariantMatrix|TestRuntimeFileBackedPatchVariantRestartAfterOwnerReceipt|TestDriveRuntimeFileBackedTwoFocusStateValidationAssessmentAndRestart|TestDriveRuntimeCompletesTypedPathAndIsRestartIdempotent|TestRequestAndSealRuntimeCandidateRecoversProviderLimitedOutputWithCompleteDocument|TestRequestAndSealRuntimeCandidateRestartsFromPersistedIncompleteOutcome|TestRequestAndSealRuntimeCandidateFailsWhenDocumentRecoveryBudgetExhausted|TestRuntimeMainlinePartialReplayClosesAttemptThenSealsCorrectedRetry|TestRuntimeEnsureCandidateFeasibleBlocksProviderWithoutKinds|TestRuntimeGovernanceDependencyPreservesSuspendedOperationBinding|TestRuntimeGovernanceTicketResolutionCommitsThroughConcreteTypedEventHubCommand|TestRuntimeFileBackedCreationSelectionCommitCrashRestart|TestStopWaitsForQueuedDecisionEvidenceHandlerBeforeClearingDependencies|TestStopWaitsForQueuedRuntimeOperationReceiptHandlerBeforeClearingDependencies|TestStopWaitsForQueuedRuntimeGovernanceTicketHandlerBeforeClearingDependencies'

run_pkg ./internal/modules/kernel/orchestrator/biz \
  -run 'TestRuntimeValidationDiscovery'

# RVC-R17/R18: Decision durable proposal saga and aggregate-owned governance
# recovery. No HTTP/CLI Resume path may reconstruct the continuation.
run_pkg ./internal/modules/blocks/decision/... \
  -run 'TestService_RuntimeGovernanceProposalStaysOpenUntilFinalize|TestService_RuntimeGovernanceRejectsUnallowedActionBeforeProposal|TestRuntimeGovernanceResolutionDoesNotResolveTicketBeforeAggregateCommit'

run_pkg ./internal/modules/kernel/orchestrator/biz \
  -run 'TestRuntimeGovernanceResolutionFileBackedRestartReplaysExactlyOnce'

# RVC-R20/R21: descriptor-driven provider schema, required-operation wire mapping,
# and concrete LLM audit DTO wire payload.
run_pkg ./internal/modules/blocks/llm/... \
  -run 'TestRuntimeCandidateSchemaDerivesPatchTargetRequirementsFromOperationContract|TestRuntimeCandidateSchemaRestrictsVariantsToSealedAuthority|TestDecodeCandidatePayloadPreservesRequiredOperationRef|TestRequestCandidateClassifiesOutputLimitSchemaTruncation|TestResolveProviderModelTargetUsesCatalogOutputCapabilityWithoutLocalCap|TestRuntimeCandidateAuthorityProjectionPreservesManifestScopedTargetGrounding|TestRuntimeProviderRequestProjectsManifestScopedC3AtRunScale|TestValidateRuntimeCandidateManifestSupportingFactsRequiresCanonicalExactBindings'

run_pkg ./internal/modules/blocks/eventstream/pkg/recordpayload \
  -run 'TestLLMUsagePayloadUsesTypedAuditDTOs'

# Continuation / unresolved rehydrate.
run_pkg ./internal/modules/application/workorchd/biz/appservice/activationcore \
  -run 'TestRuntimeBootstrapAcceptsDefinitionSeedWithoutPrecompiledProof|TestRuntimeBootstrapDefersMissingSemanticFieldsToPlanning|TestRuntimeBootstrapCompilesBroadDoDIntoSemanticPlanningSeed|TestCompileRuntimeCoverageSlicesBoundLargeDoD|TestCompileRuntimeCoverageFocusesPrependsMatchedBootstrapArtifactsInDependencyOrder|TestRuntimeBootstrapBuildsBoundedGitCapabilityStateFixture|TestCompileRuntimeCoverageCarriesProspectiveTargetCandidatesIntoLeadingDoDFocus|TestCompileRuntimeCoverageCarriesProfileDeclaredSelector'

run_pkg ./internal/modules/application/workorchd/biz/appservice/governanceports \
  -run 'TestBatchResolveDecisionViewsRejectsMixedAllowedActionsBeforeWrites'

# Projection generation recovery / ready.
run_pkg ./internal/modules/application/workorchd/biz/appservice/workspaceviewcore \
  -run 'TestStoreProjectionGenerationRecovery|TestStoreDeletedWorkspaceClearsGenerationFailure|TestStoreRestartDoesNotCarryGenerationFailures|TestManagerMetricsDoNotDriveProjectionHealth'

# Terminal authority is delivered through the typed owner chain exactly once.
run_pkg ./internal/modules/kernel/orchestrator/biz \
  -run 'TestDeliverRuntimeTerminalCreatesResultAndProjectsOwnersIdempotently|TestDeliverRuntimeTerminalUsesTypedOwnerEventContracts|TestDeliverRuntimeTerminalReplaysSameIdentityAfterOwnerCASConflict'

# P5: terminal authority is committed before projection. Recovery may only
# replay Result -> Workspace -> Run delivery, including every response-loss
# boundary, and must not re-drive a candidate or operation.
run_pkg ./internal/modules/kernel/orchestrator/biz \
  -run 'TestDeliverRuntimePrerequisiteRefreshExhaustedRestartsAfterTerminalPersistenceBeforeResult|TestDeliverRuntimeTerminalRestartsAfterResultPersistenceBeforeOwnerProjection|TestDeliverRuntimeTerminalRestartsAfterOwnerProjectionAcknowledgementLoss|TestRuntimeStartupRecoveryDeliversPendingTerminalThroughOwnerChain'

run_pkg ./internal/modules/application/workorchd/biz/appservice/readmodelports \
  -run 'TestRunObservabilityHydratesLLMUsagePayloads|TestRunSnapshotBuildsSnapshotFromReaders'

run_pkg ./internal/modules/application/workorchd/service/server \
  -run 'TestServerMetricsObserveRunStateIsExactlyOnce'

# WP-8 boundary: activation acknowledgement is asynchronous and must seal the
# first resolved model target into the workspace; TUI resume/exit only manage
# input and projection lifecycle, never reconstruct runtime authority.
run_pkg ./internal/modules/application/workorchd/service/server \
  -run 'TestWorkorchDActivationHTTPProjectsRequestID|TestWorkorchDActivationHTTPWaitsForOwnerAdmission'

run_pkg ./internal/services/workorch/service/cli \
  -run 'TestRunResumeUsesUnifiedWorkspaceRunCommand'

run_pkg ./internal/services/workorch/service/tui \
  -run 'TestModelRunResumeCommandUsesWorkspaceScopedResume|TestModelRunResumeWithoutLiveRunDoesNotPredeclareContinuation|TestModelRunRestartRequestsWorkspaceScopedFreshActivation|TestModelExitCommandQuits|TestModelExitCommandDefersProjectionUnsubscribe|TestModelExitCommandWorksDuringModelSelection|TestProductionTUIUsesTypedProjectionSubscriptionOnly'

echo "runtime positive-convergence file verification passed" | tee -a "$LOG"
echo "artifacts=$ARTIFACT_DIR" | tee -a "$LOG"
